ALTER TABLE inventory_balances ADD COLUMN reserved_quantity NUMERIC(19,6) NOT NULL DEFAULT 0, ADD CONSTRAINT ck_inventory_reserved CHECK(reserved_quantity>=0 AND reserved_quantity<=on_hand_quantity);
CREATE TABLE inventory_reservations(id UUID PRIMARY KEY,tenant_id UUID NOT NULL REFERENCES organizations(id),reference_type VARCHAR(32) NOT NULL,reference_id VARCHAR(128) NOT NULL,status VARCHAR(16) NOT NULL,requested_quantity NUMERIC(19,6) NOT NULL,unit_code VARCHAR(8) NOT NULL,expires_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL,created_by VARCHAR(255) NOT NULL,updated_at TIMESTAMPTZ NOT NULL,version BIGINT NOT NULL DEFAULT 0,idempotency_key VARCHAR(128) NOT NULL,request_fingerprint CHAR(64) NOT NULL,UNIQUE(tenant_id,id),UNIQUE(tenant_id,idempotency_key),CHECK(reference_type='MANUAL_HOLD'),CHECK(status IN('ACTIVE','RELEASED','EXPIRED')),CHECK(requested_quantity>0));
CREATE TABLE inventory_reservation_allocations(id UUID PRIMARY KEY,tenant_id UUID NOT NULL,reservation_id UUID NOT NULL,variant_id UUID NOT NULL,warehouse_id UUID NOT NULL,location_id UUID NOT NULL,lot_id UUID,serial_id UUID,quantity NUMERIC(19,6) NOT NULL,unit_code VARCHAR(8) NOT NULL,created_at TIMESTAMPTZ NOT NULL,UNIQUE(tenant_id,reservation_id,id),FOREIGN KEY(tenant_id,reservation_id)REFERENCES inventory_reservations(tenant_id,id)ON DELETE RESTRICT,FOREIGN KEY(tenant_id,variant_id)REFERENCES catalog_product_variants(tenant_id,id)ON DELETE RESTRICT,FOREIGN KEY(tenant_id,warehouse_id,location_id)REFERENCES warehouse_locations(tenant_id,warehouse_id,id)ON DELETE RESTRICT,FOREIGN KEY(tenant_id,variant_id,lot_id)REFERENCES inventory_lots(tenant_id,variant_id,id)ON DELETE RESTRICT,FOREIGN KEY(tenant_id,variant_id,serial_id)REFERENCES inventory_serials(tenant_id,variant_id,id)ON DELETE RESTRICT,CHECK(quantity>0));
CREATE INDEX idx_reservation_expiry ON inventory_reservations(tenant_id,status,expires_at)WHERE status='ACTIVE';CREATE INDEX idx_reservation_reference ON inventory_reservations(tenant_id,reference_type,reference_id);CREATE INDEX idx_reservation_variant_status ON inventory_reservation_allocations(tenant_id,variant_id,reservation_id);CREATE INDEX idx_reservation_location ON inventory_reservation_allocations(tenant_id,warehouse_id,location_id);CREATE INDEX idx_reservation_lot ON inventory_reservation_allocations(tenant_id,lot_id);CREATE INDEX idx_reservation_serial ON inventory_reservation_allocations(tenant_id,serial_id);
CREATE FUNCTION prevent_reservation_allocation_mutation()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN RAISE EXCEPTION 'reservation allocation is immutable' USING ERRCODE='55000';END$$;CREATE TRIGGER reservation_allocations_immutable BEFORE UPDATE OR DELETE ON inventory_reservation_allocations FOR EACH ROW EXECUTE FUNCTION prevent_reservation_allocation_mutation();
INSERT INTO permissions(permission_key,description)VALUES('inventory-reservation:read','Read inventory reservations'),('inventory-reservation:manage','Create and release inventory reservations')ON CONFLICT DO NOTHING;
INSERT INTO role_permissions(tenant_id,role_id,permission_key)SELECT r.tenant_id,r.id,p.permission_key FROM roles r CROSS JOIN permissions p WHERE r.system_role AND r.name='ORGANIZATION_ADMIN' AND p.permission_key LIKE 'inventory-reservation:%'ON CONFLICT DO NOTHING;INSERT INTO role_permissions(tenant_id,role_id,permission_key)SELECT r.tenant_id,r.id,'inventory-reservation:read' FROM roles r WHERE r.system_role AND r.name IN('READ_ONLY','AUDITOR')ON CONFLICT DO NOTHING;
